lemma apply_mob_some_of_ne {a b c d : ℚ} (h : a * d - b * c ≠ 0) {z : Qbar}
    (hz : (c : Qbar) * z + d ≠ 0) :
    (mob a b c d h).apply (some z) = some (((a : Qbar) * z + b) / ((c : Qbar) * z + d))

lemma crit_sepPoly {m n : ℕ} (hm : m ≠ 0) (hn : n ≠ 0) {z : Qbar}
    (hz : aeval z (derivative (sepPoly m n)) = 0) :
    z = 0 ∨ z = 1 ∨ z = (((m : ℚ) / ((m : ℚ) + n) : ℚ) : Qbar)

theorem aeval_smul_of_isHomogeneous {n : ℕ} {a : MvPolynomial (Fin 2) k}
    (ha : a.IsHomogeneous n) (c : R) (g : Fin 2 → R) :
    aeval (c • g) a = c ^ n * aeval g a

